import { InteractiveBrowserCredential } from "@azure/identity";

const credential = new InteractiveBrowserCredential({ tenantId: "common" });

export async function callAgent(agentName: string, agentVersion: string, input: string) {
  const token = await credential.getToken("https://ai.azure.com/.default");

  const res = await fetch(
    `${process.env.FOUNDRY_PROJECT_ENDPOINT}/responses?api-version=v1`,
    {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${token.token}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        input: [{ role: "user", content: input }],
        agent: { name: agentName, version: agentVersion, type: "agent_reference" },
      }),
    }
  );

  if (!res.ok) {
    const err = await res.text();
    throw new Error(`Agent call failed: ${res.status} ${err}`);
  }

  const data = await res.json();
  return data.output_text;
}